  "denied": [
    { "id": "Microsoft.Extensions.Http.Polly", "reason": "deprecated integration; use Microsoft.Extensions.Http.Resilience", "owner": "add-dependency" },
    { "id": "Polly.Extensions.Http", "reason": "deprecated integration; use Microsoft.Extensions.Http.Resilience", "owner": "add-dependency" },
    { "id": "FluentValidation.AspNetCore", "reason": "deprecated automatic-validation integration", "owner": "aspnet-error-handling" },
    { "id": "Serilog.Sinks.Elasticsearch", "reason": "deprecated sink package; use Elastic.Serilog.Sinks", "owner": "logging" }
  ],
  "approvalRequired": [

function checkNugetIds(ids, rules, rel, findings) {
  for (const id of ids) {
    if (/\$\(/.test(id || '')) { findings.push(`${rel}: package id '${id}' uses an MSBuild property; the hook does not evaluate MSBuild, so confirm the resolved package is allowed (owner: add-dependency).`); continue; }
    for (const r of packageMatches(id, rules.nugetDenied)) findings.push(`${rel}: '${id}' must not be added — ${r.reason} (owner: ${r.owner}).`);
    for (const r of packageMatches(id, rules.nugetApproval)) findings.push(`${rel}: '${id}' requires approval — ${r.reason} (owner: ${r.owner}). Remove it unless the user approved it.`);
  }
}
